import{_ as o,H as a,f as t,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"27 | 让我们一起探索Medooze的具体实现吧（上）","description":"","frontmatter":{},"headers":[{"level":2,"title":"流媒体服务器Medooze","slug":"流媒体服务器medooze","link":"#流媒体服务器medooze","children":[{"level":3,"title":"1. Medooze的 SFU 模型","slug":"_1-medooze的-sfu-模型","link":"#_1-medooze的-sfu-模型","children":[]},{"level":3,"title":"2. 录制回放模型","slug":"_2-录制回放模型","link":"#_2-录制回放模型","children":[]},{"level":3,"title":"3. 推流模型","slug":"_3-推流模型","link":"#_3-推流模型","children":[]}]},{"level":2,"title":"Medooze架构分析","slug":"medooze架构分析","link":"#medooze架构分析","children":[{"level":3,"title":"1. 源码目录结构","slug":"_1-源码目录结构","link":"#_1-源码目录结构","children":[]},{"level":3,"title":"2. 对外接口介绍","slug":"_2-对外接口介绍","link":"#_2-对外接口介绍","children":[]},{"level":3,"title":"3. Medooze结构","slug":"_3-medooze结构","link":"#_3-medooze结构","children":[]}]},{"level":2,"title":"什么是SWIG","slug":"什么是swig","link":"#什么是swig","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考时间","slug":"思考时间","link":"#思考时间","children":[]}],"relativePath":"从0打造音视频直播系统/27-让我们一起探索Medooze的具体实现吧（上）.md","filePath":"从0打造音视频直播系统/27-让我们一起探索Medooze的具体实现吧（上）.md","lastUpdated":1779818563000}'),r={name:"从0打造音视频直播系统/27-让我们一起探索Medooze的具体实现吧（上）.md"};function s(n,e,l,d,p,E){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_27-让我们一起探索medooze的具体实现吧-上" tabindex="-1">27 | 让我们一起探索Medooze的具体实现吧（上） <a class="header-anchor" href="#_27-让我们一起探索medooze的具体实现吧-上" aria-label="Permalink to &quot;27 | 让我们一起探索Medooze的具体实现吧（上）&quot;">​</a></h1><p>在咱们专栏的第一模块，我向你介绍了如何使用 WebRTC 进行实现音视频互动。随着 Google 对 WebRTC 的大力推广，目前主流的浏览器都支持了 WebRTC。WebRTC 最主要的功能就是提供端对端的音视频通信，其可以借助 STUN/TURN 服务器完成 NAT 穿越，实现两个端点之间的直接通信。</p><p>1对1的实时通信无疑是 WebRTC 最主要的应用场景，但你是否想过 WebRTC 可以通过浏览器实现多人音视频会议呢？更进一步，你是否想过 WebRTC 可以实现一些直播平台中上万人甚至几十万人同时在线的场景呢？</p><p>如果你对上面的问题感兴趣，那本文将让你对上面问题有个全面的了解，接下来就让我们一起开启本次神秘之旅吧！</p><h2 id="流媒体服务器medooze" tabindex="-1">流媒体服务器Medooze <a class="header-anchor" href="#流媒体服务器medooze" aria-label="Permalink to &quot;流媒体服务器Medooze&quot;">​</a></h2><p>正如我们在 <a href="https://time.geekbang.org/column/article/134284" target="_blank" rel="noreferrer">《25 | 那些常见的流媒体服务器，你该选择谁？》</a> 一文中介绍的，要实现多个浏览器之间的实时音视频通信（比如音视频会议），那么就一定需要一个支持 WebRTC 协议的流媒体服务器。目前，有很多开源的项目支持 WebRTC 协议， Medooze 就是其中之一。</p><p>Medooze的功能十分强大，通过它你既可以实现 SFU 类型的流媒体服务器，也可以实现MCU类型的流媒体服务器。而且，它还支持多种媒体流接入，也就是说，你除了可以通过浏览器（WebRTC）向Medooze分享音视频流之外，还可以使用 FFmpeg/VLC 等工具将 RTMP 协议的音视频流推送给 Meoodze。更加神奇的是，无论是 WebRTC 分享的音视频流还是 RTMP 格式的音视频流通过Medooze转发后，浏览器就可以将 FFmpeg/VLC推的流显示出来，而VLC也可以将 WebRTC 分享的音视频显示出来，这就是 Medooze 的强大之处。</p><p>接下来，我们将从Medooze的 SFU 模型、录制回放模型和推流模型这三个方面向你全面、详细地介绍 Medooze。</p><h3 id="_1-medooze的-sfu-模型" tabindex="-1">1. Medooze的 SFU 模型 <a class="header-anchor" href="#_1-medooze的-sfu-模型" aria-label="Permalink to &quot;1\\. Medooze的 SFU 模型&quot;">​</a></h3><p>SFU 模型的概念我们已经在 <a href="https://time.geekbang.org/column/article/132863" target="_blank" rel="noreferrer">《24 | 多人音视频实时通讯是怎样的架构？》</a> 一文中做过介绍了，这里就不再赘述了！下面这张图是 Medooze 实现 SFU 服务器的大体结构图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/f9d36818221629f67f06a49eb4003294.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/f9d36818221629f67f06a49eb4003294.png" alt=""></a></p><p>Medooze SFU 模型结构图</p><p>图的最外层标有 Browser 的模块表示浏览器，在本图中就是表示基于浏览器的 WebRTC 终端。</p><p>图的中间标有 Medooze 的模块是服务器，实现了 SFU 功能。其中 DTLSICETransport 既是传输层（控制socket收发包），也是一个容器，在该容器中可以放IncomingStream 和 OutgoingStream。</p><ul><li>IncomingStream，代表某客户端共享的音视频流。</li><li>OutgoingStream，代表某个客户端需要观看的音视频流。</li></ul><p>你也可以把它们直接当作是两个队列，IncomingStream 是输入队列，OutgoingStream是输出队列。</p><p>有了上面这些概念，那我们来看看在Medooze中从一端进来的音视频流是怎么中转给其他人的。</p><ul><li>首先，Browser 1 推送音视频流给 Medooze，Medooze 通过 DTLSICETransport 接收音视频数据包，然后将它们输送到 IncomingStream 中。</li><li>然后，Medooze 再将此流分发给 Browser 2、Browser 3、Browser 4 的 OutgoingStream。</li><li>最后，Medooze 将 OutgoingStream 中的音视频流通过 DTLSICETransport 传输给浏览器客户端，这样 Browser 2、Browser 3、Browser 4 就都能看到 Browser 1 共享的音视频流了。</li></ul><p>同理，Browser 3推送的音视频流也是按照上面的步骤操作，最终分发到其他端，其他端也就看/听到 Browser 3 的音视频了。</p><p>通过以上步骤就实现了多人之间的音视频互动。</p><h3 id="_2-录制回放模型" tabindex="-1">2. 录制回放模型 <a class="header-anchor" href="#_2-录制回放模型" aria-label="Permalink to &quot;2\\. 录制回放模型&quot;">​</a></h3><p>下图是Medooze的录制回放模型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/22f170520f6cb6f1f786472b946b3fc6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/22f170520f6cb6f1f786472b946b3fc6.png" alt=""></a></p><p>录制回放模型</p><p>这张图是一个典型的音视频会议中服务器端录制的模型。下面我们就来看看它运转的过程：</p><ul><li>Browser 1 推送音视频流到 Medooze，Medooze使用 IncomingStream 代表这一路流。</li><li>Medooze 将 IncomingStream 流分发给参会人 Browser 2 的 OutgoingStream，并同时将流分发给 Recorder。</li><li>Recorder 是一个录制模块，将实时 RTP 流转换成 MP4 格式，并保存到磁盘。</li></ul><p>通过以上步骤，Medooze就完成了会议中实时录制的功能。</p><p>如果，用户想回看录制好的多媒体文件，那么只需要按以下步骤操作即可：</p><ul><li>首先，告诉 Medooze 的 Player 模块，之前录制好的 MP4 文件存放在哪个路径下。</li><li>接着，Player 从磁盘读取 MP4 文件，并转换成 RTP 流推送给 IncomingStream。</li><li>然后，Medooze 从 IncomingStream 获取 RTP流， 并分发给 Browser 3 的 OutgoingStream。</li><li>最后，再经过 DTLSICETransport 模块传给浏览器。</li></ul><p>这样就可以看到之前录制好的音视频了。</p><h3 id="_3-推流模型" tabindex="-1">3. 推流模型 <a class="header-anchor" href="#_3-推流模型" aria-label="Permalink to &quot;3\\. 推流模型&quot;">​</a></h3><p>下面是 Medooze的推流模型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/1d5eb2f6019e8a1685f05a8f70dcf38e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/1d5eb2f6019e8a1685f05a8f70dcf38e.png" alt=""></a></p><p>推流模型</p><p>通过前面的讲解，再理解这个模型就非常简单了。下面让我们来看一下推流的场景吧：</p><ul><li>首先，用 VLC 播放器推送一路 RTP 流到 Medooze。</li><li>然后，Medooze 将此流分发给 Browser 2、Browser 3、Browser 4。</li></ul><p>没错，Medooze 推流的场景就是这么简单，只需要通过 FFMPEG/VLC 向 Medooze的某个房间推一路 RTP 流，这样加入到该房间的其他用户就可以看到推送的这路音视频流了。</p><p>学习了上面的知识后，你是不是对 Medooze 的基本功能以及运行流程已经了然于胸了呢？现在是不是迫切地想知道Medooze内部是如何实现这些功能的？那么下面我们就来分析一下Medooze的架构。</p><h2 id="medooze架构分析" tabindex="-1">Medooze架构分析 <a class="header-anchor" href="#medooze架构分析" aria-label="Permalink to &quot;Medooze架构分析&quot;">​</a></h2><p>由于 Medooze 是一个复杂的流媒体系统，所以在它的开源目录下面有很多子项目来支撑这个系统。其中一个核心项目是 media-server，它是 C++ 语言实现的，主要是以 API 的形式提供诸多流媒体功能，比如 RTMP 流、RTP 流、录制、回放、WebRTC 的支持等。另外一个项目是 media-server-node，此项目是 Node.js 实现的，将 media-server 提供的 C++ API 包装成JavaScript接口，以利于通过 Node.js 进行服务器业务控制逻辑的快速开发。</p><p>接下来，我们就以 media-server-node 作为切入点，对此服务展开分析。</p><h3 id="_1-源码目录结构" tabindex="-1">1. 源码目录结构 <a class="header-anchor" href="#_1-源码目录结构" aria-label="Permalink to &quot;1\\. 源码目录结构&quot;">​</a></h3><p>media-server-node 是基于 Node.js 的一个项目，在实际开发过程中，只需要执行下面的命令就可以将 media-server-node 编译安装到你的系统上。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install media-server-node --save</span></span></code></pre></div><p>这里我们对 media-server-node 源码目录结构做一个简要的说明，一方面是给你一个大概的介绍，另一方面也做一个铺垫，便于我们后续的分析。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/b871ba25a899ae1692fd67b75909e2ef.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/b871ba25a899ae1692fd67b75909e2ef.png" alt=""></a></p><p>通过对上面源码目录结构的分析，你可以看出它的结构还是蛮清晰的，当你要分析每一块的具体内容时，直接到相应的目录下查看具体实现就好了。</p><p>目录结构介绍完后，我们再来看看 Medooze 暴露的几个简单接口吧！</p><h3 id="_2-对外接口介绍" tabindex="-1">2. 对外接口介绍 <a class="header-anchor" href="#_2-对外接口介绍" aria-label="Permalink to &quot;2\\. 对外接口介绍&quot;">​</a></h3><p>media-server-node 采用了JavaScript ES6 的语法，各个模块都是导出的，所以每一个模块都可以供应用层调用。这里主要讲解一下 MediaServer 模块暴露的接口：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/9b13d6ff2b8e113dc3b4011d2088d406.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/9b13d6ff2b8e113dc3b4011d2088d406.png" alt=""></a></p><p>如果你对JavaScript 非常精通的话，你可能会觉得这几个接口实在太简单了，但Medooze 设计这些接口的理念就是尽量简单，这也符合我们定义接口的原则。对于这些接口的使用我们会在后面的文章中做讲解，现在你只需要知道这几个接口的作用是什么就好了。</p><h3 id="_3-medooze结构" tabindex="-1">3. Medooze结构 <a class="header-anchor" href="#_3-medooze结构" aria-label="Permalink to &quot;3\\. Medooze结构&quot;">​</a></h3><p>讲到Medooze结构，也许稍微有点儿抽象、枯燥，不是那么有意思，不过只要你多一点点耐心按照我的思路走，一定可以将其理解的。</p><p>在正式讲解Medooze结构之前，我们还需要介绍一个知识点：在 Node.js中，JavaScript 与 C++ 是如何相互调用的呢？知道其原理对你理解Medooze的运行机制有非常大的帮助，所以这里我做一些简单的介绍。JavaScript与C++调用关系图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/d864639fb361e76993dd824a21b3085d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/d864639fb361e76993dd824a21b3085d.png" alt=""></a></p><p>JavaScript 与 C++ 调用关系图</p><p>我们都知道 Node.js 解析JavaScript脚本使用的是 Google V8 引擎，实际上 V8 引擎就是连接 JavaScript 与 C/C++ 的一个纽带，你也可以把它理解为一个代理。</p><p>在 Node.js 中，我们可以根据自己的需要，按V8引擎的规范为它增加C/C++模块，这样 Node.js就可以将我们写好的C++模块注册到V8 引擎中了。注册成功之后，V8 引擎就知道我们这个模块都提供了哪些服务（API）。</p><p>此时，JavaScript 就可以通过 V8 引擎调用 C/C++ 编写的接口了。接口执行完后，再将执行的结果返回给 JavaScript。以上就是JavaScript 与 C/C++ 相互调用的基本原理。</p><p>了解了上面的原理后，咱们言归正传，还是回到我们上面讲的Medooze整体结构这块知识上来。从大的方面讲， Medooze 结构可以分为三大部分，分别是:</p><ul><li><strong>media server node</strong>，主要是 ICE 协议层的实现，以及对 Media server Native API 的封装。</li><li><strong>SWIG node addon</strong>，主要是实现了 Node.js JavaScript 和 C++ Native 之间的融合，即可以让 JavaScript 直接调用 C/C++实现的接口。</li><li><strong>media server</strong>，是Medooze 流媒体服务器代码的实现，比如WebRTC协议栈、网络传输、编解码的实现等，都是在该模块实现的。</li></ul><p>让我们看一下 Medooze 整体结构中三个核心组件的作用，以及它们之间的相互依赖关系。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/4e280e6884f1a6e1b3123617c820e73e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/4e280e6884f1a6e1b3123617c820e73e.png" alt=""></a></p><p>组件关系图</p><p>从这张图我们可以知道，Medooze的整体结构也是蛮复杂的，但若仔细观察，其实也不是很难理解。下面我们就来详细描述一下这张图吧！</p><ul><li>图中标有 WebRTC 的组件实现了 WebRTC 协议栈，它是用于实现多方音视频会议的。</li><li>Recorder 相关的组件是实现录制的，这里录制格式是 MP4 格式。</li><li>Player 相关组件是实现录制回放的，可以将 MP4 文件推送到各个浏览器，当然是通过 WebRTC 协议了。</li><li>Streamer 相关组件是接收 RTP 流的，你可以通过 VLC 客户端推送 RTP 流给 Medooze，Medooze 然后再推送给各个浏览器。</li></ul><p>接下来，针对这些组件我们再做一个简要说明，不过这里我们就只介绍 Media server node 和 Media server 两大组件。由于 SWIG node addon 是一个 C++ Wrapper，主要用于C/C++与JavaScript脚本接口之间的转换，所以这里就不对它进行说明了。</p><p>需要注意的是，上图中的每一个组件基本是一个 Node.js 模块或者是一个 C++ 类，也有极个别组件是代表了几个类或者模块，比如SDP 其实是代表整个 SDP 协议的实现模块。</p><p><strong>Media server node 组件</strong> 中每个模块的说明如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/1c785c5fbf973db368fb84d5df1fecff.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/1c785c5fbf973db368fb84d5df1fecff.png" alt=""></a></p><p>了解了 Media server node 组件中的模块后，接下来我们再来看看 <strong>Media server 组件</strong> 中每个模块的作用，说明如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/e3d70f0bf305018f040f9c1fa0171a20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E6%89%93%E9%80%A0%E9%9F%B3%E8%A7%86%E9%A2%91%E7%9B%B4%E6%92%AD%E7%B3%BB%E7%BB%9F/images/136000/e3d70f0bf305018f040f9c1fa0171a20.png" alt=""></a></p><h2 id="什么是swig" tabindex="-1">什么是SWIG <a class="header-anchor" href="#什么是swig" aria-label="Permalink to &quot;什么是SWIG&quot;">​</a></h2><p>SWIG（Simplified Wrapper and Interface Generator ），是一个将C/C++接口转换成其他脚本语言（如JavaScript、Ruby、Perl、Tcl 和 Python）的接口转换器，可以将你想暴露的 C/C++ API 描述在一个后缀是 *.i 的文件里面，然后通过SWIG编译器就可以生成对应脚本语言的Wrapper程序了，这样对应的脚本语言（如 JavaScript）就可以直接调用 Wrapper 中的 API 了。</p><p>生成的代码可以在脚本语言的解释器平台上执行，从而实现了脚本语言调用C/C++程序API的目的。SWIG只是代码生成工具，它不需要依赖任何平台和库。</p><p>至于更详细的信息，你可以到 SWIG 的官网查看，地址在这里： <a href="http://www.swig.org/" target="_blank" rel="noreferrer">http://www.swig.org/</a> 。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本文讲解了 Medooze 的 SFU 模型、录制回放模型、推流模型等内容，并且介绍了Medooze的整体结构和核心组件的功能等。通过以上内容的讲解，你应该对 WebRTC 服务器有一个初步认知了。</p><p>除此之外，文章中也提到了WebRTC流媒体服务器的传输需要基于 DTLS-SRTP 协议以及 ICE 等相关识。这些知识在后面的文章中我们还会做更详细的介绍。</p><h2 id="思考时间" tabindex="-1">思考时间 <a class="header-anchor" href="#思考时间" aria-label="Permalink to &quot;思考时间&quot;">​</a></h2><p>通过上面的描述，你可以看到 Medooze是作为一个模块加入到 Node.js 中来提供流媒体服务器能力的，那么这种方式会不会因为 Node.js 的性能而影响到 Medooze 流媒体服务的性能呢？</p><p>欢迎在留言区与我分享你的想法，也欢迎你在留言区记录你的思考过程。感谢阅读，如果你觉得这篇文章对你有帮助的话，也欢迎把它分享给更多的朋友。</p>',83)])])}const h=o(r,[["render",s]]);export{g as __pageData,h as default};
